function handleC017Click(b){
 if(b.dataset.c017Statement!==undefined){state.classification.active=+b.dataset.c017Statement;feedback='';wrong=false;persist();render();return}
 if(b.dataset.c017Status){state.classification.answers[state.classification.active]=b.dataset.c017Status;persist();render();return}
 if(b.dataset.c017Proof){const id=b.dataset.c017Proof,i=state.contradictionEvidence.indexOf(id);if(i>=0)state.contradictionEvidence.splice(i,1);else if(state.contradictionEvidence.length<2)state.contradictionEvidence.push(id);persist();render();return}
 if(b.dataset.c017Theory!==undefined){state.attempts++;if(+b.dataset.c017Theory===2)completeC017();else{wrong=true;feedback='Belum tepat. Bukti mengesahkan masa penghantaran, tetapi tidak membuktikan siapa memasukkan catatan salah atau sebabnya.';persist();render()}return}
 if(b.hasAttribute('data-mechanic-hint')){c017Hint();return}
 switch(b.dataset.action){case'next':if([1,2,3,4,5,6,7,8].includes(state.scene)&&!state.solved[state.scene])return;state.scene++;state.sourceOpen=false;feedback='';wrong=false;persist();render();break;case'c017-hint':c017Hint();break;case'c017-review':state.sourceOpen=true;render();break;case'c017-review-close':state.sourceOpen=false;render();break;case'c017-classify':{const i=state.classification.active,answer=state.classification.answers[i];state.attempts++;if(answer===c017Statements[i].answer){state.classification.completed[i]=true;feedback=`✓ Kenyataan ${i+1} dikelaskan sebagai ${c017StatusLabels[answer]}.`;wrong=false;if(state.classification.completed.every(Boolean))state.solved[7]=true}else{feedback='Belum tepat. Bandingkan kenyataan dengan urutan masa dalam rekod sumber.';wrong=true}persist();render();break}case'c017-proof-check':state.attempts++;if(state.contradictionEvidence.length===2&&state.contradictionEvidence.includes('stock')&&state.contradictionEvidence.includes('dispatch')){state.solved[8]=true;feedback='✓ Semakan stok 3:10 dan log bertolak 3:20 menunjukkan penghantaran belum selesai pada 3:00.';wrong=false}else{feedback='Belum cukup kuat. Cari satu rekod yang menunjukkan kotak masih di kedai dan satu rekod masa ia mula bertolak.';wrong=true}persist();render();break;case'home':home=true;file=false;persist();render();break;case'file':file=true;render();break;case'closefile':file=false;render();break;case'replay':{const historical=cases.C017.record;state=fresh17();cases.C017.run=state;cases.C017.record=historical;record=historical;home=false;file=false;persist();render();break}}
 if(!b.dataset.object)return;state.attempts++;const target=state.scene===1?'jagjit':state.scene===2?'kotak kb17':state.scene===3?(!state.noteASeen?'nota a':'nota b'):state.scene===4?'rekod stok':state.scene===5?'log penghantaran':state.scene===6?'resit balai':'';if(b.dataset.object!==target){wrong=true;feedback='Belum tepat. Cari sumber yang disebut dalam arahan.';persist();render();return}if(!state.sceneProgress.mathRecords.includes(target))state.sceneProgress.mathRecords.push(target);wrong=false;
 if(state.scene===1){state.solved[1]=true;feedback='✓ Jagjit menerangkan masalah dua nota.'}
 else if(state.scene===2){state.solved[2]=true;state.cluesFound=1;feedback='✓ Tag KB-17 sepadan dengan kedua-dua nota.'}
 else if(state.scene===3){if(target==='nota a'){state.noteASeen=true;state.cluesFound=Math.max(state.cluesFound,2);feedback='✓ Nota A dibaca. Sekarang cari Nota B.'}else{state.noteBSeen=true;state.solved[3]=true;feedback='✓ Kedua-dua nota telah dibaca.'}}
 else if(state.scene===4){state.solved[4]=true;state.cluesFound=3;feedback='✓ Rekod stok 3:10 ditemui.'}
 else if(state.scene===5){state.solved[5]=true;state.cluesFound=4;feedback='✓ Log bertolak 3:20 ditemui.'}
 else if(state.scene===6){state.solved[6]=true;state.cluesFound=5;feedback='✓ Resit penerimaan 3:40 ditemui.'}
 persist();render()
}

