function handleC019Click(b){
 if(b.dataset.perspectivePosition){const [id,i]=b.dataset.perspectivePosition.split(':');state.viewpoints[id]=+i;persist();render();return}
 if(b.dataset.perspectiveCompatible!==undefined){state.compatibility=+b.dataset.perspectiveCompatible;persist();render();return}
 if(b.dataset.c019Inference!==undefined){state.attempts++;state.inference=+b.dataset.c019Inference;if(state.inference===1){state.solved[8]=true;wrong=false;feedback='✓ Betul. Ayyash melihat persediaan, bukan bukti bahawa aktiviti sudah bermula.'}else{wrong=true;feedback='Belum tepat. Bezakan orang yang membuat persediaan dengan masa aktiviti rasmi bermula.'}persist();render();return}
 if(b.dataset.c019Evidence){const id=b.dataset.c019Evidence,i=state.evidence.indexOf(id);if(i>=0)state.evidence.splice(i,1);else if(state.evidence.length<2)state.evidence.push(id);persist();render();return}
 if(b.dataset.c019Theory!==undefined){state.attempts++;if(+b.dataset.c019Theory===2)completeC019();else{wrong=true;feedback='Belum tepat. Gunakan tempat pemerhatian, pelan kawasan dan masa dalam log penganjur.';persist();render()}return}
 switch(b.dataset.action){
  case'next':if([1,2,3,4,5,6,7,8,9].includes(state.scene)&&!state.solved[state.scene])return;state.scene++;state.sourceOpen=false;feedback='';wrong=false;persist();render();return;
  case'c019-hint':c019Hint();return;
  case'c019-review':state.sourceOpen=!state.sourceOpen;persist();render();return;
  case'c019-compare-check':state.attempts++;if(state.viewpoints.xiao===0&&state.viewpoints.ayyash===1&&state.compatibility===0){state.solved[7]=true;wrong=false;feedback='✓ Kedua-dua cerita boleh benar kerana saksi melihat kawasan berbeza.'}else{wrong=true;feedback='Belum tepat. Semak tempat Xiao Feng dan Ayyash pada pelan kawasan.'}persist();render();return;
  case'c019-evidence-check':state.attempts++;if(state.evidence.length===2&&state.evidence.includes('plan')&&state.evidence.includes('log')){state.solved[9]=true;wrong=false;feedback='✓ Pelan menerangkan perbezaan tempat, manakala log mengesahkan masa sebenar.'}else{wrong=true;feedback='Bukti itu belum cukup kuat. Pilih satu sumber tentang tempat dan satu rekod rasmi tentang masa.'}persist();render();return;
  case'home':home=true;file=false;persist();render();return;
  case'file':file=true;render();return;
  case'closefile':file=false;render();return;
  case'replay':{const historical=cases.C019.record;state=fresh19();cases.C019.run=state;cases.C019.record=historical;record=historical;home=false;file=false;persist();render();return}
 }
 if(!b.dataset.object)return;state.attempts++;const object=b.dataset.object;
 if(state.scene===3){const map={'meja pendaftaran depan':'front','kawasan persediaan belakang':'rear'};const area=map[object];if(!area){wrong=true;feedback='Cari kawasan meja pendaftaran di depan atau kawasan persediaan di belakang.'}else{if(!state.areasFound.includes(area))state.areasFound.push(area);wrong=false;feedback=`✓ Kawasan ${area==='front'?'depan':'belakang'} dikenal pasti.`;if(state.areasFound.length===2)state.solved[3]=true}persist();render();return}
 const target={1:'xiao feng perspektif',2:'ayyash perspektif',4:'pelan kawasan aktiviti',5:'jadual rasmi aktiviti',6:'log penganjur aktiviti'}[state.scene];
 if(object!==target){wrong=true;feedback='Belum tepat. Cari sumber yang disebut dalam arahan.';persist();render();return}
 if(!state.sceneProgress.parkPerspectives.includes(target))state.sceneProgress.parkPerspectives.push(target);
 if(state.scene===1)c019CompleteClue(1,'Kenyataan Xiao Feng direkodkan.');else if(state.scene===2)c019CompleteClue(2,'Kenyataan Ayyash direkodkan.');else if(state.scene===4)c019CompleteClue(3,'Pelan membezakan kawasan depan dan belakang.');else if(state.scene===5)c019CompleteClue(4,'Jadual rasmi mengesahkan masa yang dirancang.');else if(state.scene===6)c019CompleteClue(5,'Log penganjur mengesahkan masa sebenar.')
}
